// Concatenates supabase/migrations/*.sql into ONE file you can paste into the Supabase SQL editor.
// Safe to re-run: every migration is idempotent. Usage: node scripts/bundle-migrations.mjs
import { readdirSync, readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { join } from "node:path";

const root = new URL("..", import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, "$1");
const dir = join(root, "supabase", "migrations");
const files = readdirSync(dir).filter((f) => f.endsWith(".sql")).sort();
const out = [
  "-- IndicoRica: ALL migrations in order. GENERATED by scripts/bundle-migrations.mjs. Do not edit.",
  "-- Idempotent: safe to run more than once. Paste into Supabase > SQL Editor and click Run.",
  "-- Expect a 'destructive operations' warning: it is triggered by DROP POLICY IF EXISTS / REVOKE.",
  "",
  ...files.flatMap((f) => [`-- ===== ${f} =====`, readFileSync(join(dir, f), "utf8"), ""]),
].join("\n");
mkdirSync(join(root, "supabase", "bundles"), { recursive: true });
writeFileSync(join(root, "supabase", "bundles", "all-migrations.sql"), out);
console.log(`bundled ${files.length} migrations (${out.length} bytes)`);
